// Some portions generated by Claude
/**
 * Orphans: cards that share no drawn link with any other card. They are gathered into one grid per card colour (values,
 * blank nodes, and IRIs by their primary rdf:type, as `nodeVisual` colours them) and the grids into one block, which the
 * caller packs a component gap away from everything else: the whitespace says none of it is connected, the grids say
 * what kind of thing each orphan is.
 */
import type {GraphNode} from './graph-types.ts';
import {packShelves, type PackItem} from './graph-layout-packing.ts';
import {LAYOUT_SPACING as gap} from './graph-layout-spacing.ts';

type Point = {x: number; y: number};
type Size = {width: number; height: number};

/** The grid an orphan joins: one per card colour. Untyped IRIs and IRIs whose types are still loading share one. */
export function orphanKey(node: GraphNode) {
  return node.kind === 'iri' ? `iri:${node.types?.[0]?.id ?? ''}` : node.kind;
}

/**
 * Centres for the orphan `cards`, the block's top-left corner at the origin. Each grid has columns as wide as its widest
 * card and rows as tall as its tallest, cards in label order, shaped like the view; the grids go in rows of a block
 * shaped like the view, a group gap between them.
 */
export function layoutOrphans(cards: readonly number[], node: (card: number) => GraphNode, size: (card: number) => Size,
  aspectRatio: number): Map<number, Point> {
  const groups = new Map<string, number[]>();
  for (const card of cards) {
    const key = orphanKey(node(card));
    const group = groups.get(key);
    if (group) group.push(card); else groups.set(key, [card]);
  }
  const typeLabel = (card: number) => node(card).types?.[0]?.label ?? '';
  const ordered = [...groups.values()].sort((a, b) => b.length - a.length ||
    (typeLabel(a[0]) < typeLabel(b[0]) ? -1 : typeLabel(a[0]) > typeLabel(b[0]) ? 1 : 0) ||
    (orphanKey(node(a[0])) < orphanKey(node(b[0])) ? -1 : 1));
  const grids = ordered.map(group => grid(group, node, size, aspectRatio));
  const items: PackItem[] = grids.map(g => ({boxes: [...g].map(([card, at]) => {
    const {width, height} = size(card);
    return {minX: at.x - width / 2, maxX: at.x + width / 2, minY: at.y - height / 2, maxY: at.y + height / 2};
  }), segments: []}));
  const offsets = packShelves(items, aspectRatio, gap.groupGap);
  const centres = new Map<number, Point>();
  let minX = Infinity, minY = Infinity;
  grids.forEach((g, k) => g.forEach((at, card) => {
    const x = at.x + offsets[k].x, y = at.y + offsets[k].y, {width, height} = size(card);
    centres.set(card, {x, y});
    minX = Math.min(minX, x - width / 2); minY = Math.min(minY, y - height / 2);
  }));
  for (const at of centres.values()) { at.x -= minX; at.y -= minY; }
  return centres;
}

/** One group's grid, its top-left corner at the origin. */
function grid(group: number[], node: (card: number) => GraphNode, size: (card: number) => Size, aspectRatio: number) {
  const key = (card: number) => `${node(card).label}\u0000${node(card).id}`;
  const sorted = [...group].sort((a, b) => (key(a) < key(b) ? -1 : key(a) > key(b) ? 1 : 0));
  let cardWidth = 0, cardHeight = 0;
  for (const card of sorted) { cardWidth = Math.max(cardWidth, size(card).width); cardHeight = Math.max(cardHeight, size(card).height); }
  const cellWidth = cardWidth + gap.nodeGapX, cellHeight = cardHeight + gap.nodeGapY, n = sorted.length;
  // The column count whose grid is shaped most like the view; fewer columns on a tie.
  let columns = 1, best = Infinity;
  for (let c = 1; c <= n; c++) {
    const rows = Math.ceil(n / c), skew = Math.abs(Math.log((c * cellWidth - gap.nodeGapX) / (rows * cellHeight - gap.nodeGapY) / aspectRatio));
    if (skew < best - 1e-9) { best = skew; columns = c; }
  }
  const centres = new Map<number, Point>();
  sorted.forEach((card, i) => centres.set(card, {x: (i % columns) * cellWidth + cardWidth / 2, y: Math.floor(i / columns) * cellHeight + cardHeight / 2}));
  return centres;
}
